.pf td, .pf th { border: .5pt solid #cbd5e1; padding: 1.4mm 2mm; vertical-align: top; }
.pf th { background: #f1f5f9; text-align: left; font-weight: 600; }
.pf .stamm td { border: none; padding: .8mm 0; }
.pf .stamm td.l { color: #64748b; width: 32mm; }
.pf .badge { display: inline-block; padding: .4mm 2mm; border-radius: 2mm;
             color: #fff; font-size: 7.5pt; font-weight: 600; }
.pf .fotos { display: flex; flex-wrap: wrap; gap: 2mm; margin-top: 2mm; }
.pf .foto { width: 52mm; }
.pf .foto img { width: 100%; border: .5pt solid #cbd5e1; border-radius: 1mm; }
.pf .foto .bu { font-size: 7pt; color: #475569; margin-top: .6mm; }
.pf .sig { display: flex; gap: 8mm; margin-top: 6mm; }
.pf .sig .feld { flex: 1; }
.pf .sig img { height: 18mm; display: block; }
.pf .sig .linie { border-top: .5pt solid #0f172a; margin-top: 1mm; padding-top: 1mm;
