#!/usr/bin/env python3
"""Erzeugt die Print-Format-JSONs (PDF-Ausgabe, FA-090/FA-091).

Die Jinja-Templates liegen als lesbares HTML in diesem Skript und werden in das
von Frappe erwartete JSON-Format geschrieben.
"""

from __future__ import annotations

import json
import pathlib

ROOT = pathlib.Path(__file__).resolve().parent.parent
ZIEL = ROOT / "oekovolt_baudoku" / "baudoku" / "print_format"
TS = "2026-09-15 08:00:00.000000"

