  baufortschritt: (tage = 60) =>
    methode('oekovolt_baudoku.api.dashboard.baufortschritt', { tage }, 'GET'),
  protokollStatistik: (jahr?: number) =>
    methode('oekovolt_baudoku.api.dashboard.protokoll_statistik', { jahr }, 'GET'),

  vorlagenFuerAnlage: (anlage: string) =>
    methode('oekovolt_baudoku.api.protokoll.vorlagen_fuer_anlage', { anlage }, 'GET'),
  vorlageKomplett: (vorlage: string) =>
    methode('oekovolt_baudoku.api.protokoll.vorlage_komplett', { vorlage }, 'GET'),
  protokollStarten: (parameter: Record<string, unknown>) =>
    methode('oekovolt_baudoku.api.protokoll.protokoll_starten', parameter),
  ergebnisSpeichern: (protokoll: string, pruefpunkt_key: string, werte: unknown) =>
    methode('oekovolt_baudoku.api.protokoll.ergebnis_speichern', { protokoll, pruefpunkt_key, werte }),
  unterschreiben: (parameter: Record<string, unknown>) =>
    methode('oekovolt_baudoku.api.protokoll.unterschreiben', parameter),
  mangelAusPruefpunkt: (parameter: Record<string, unknown>) =>
    methode('oekovolt_baudoku.api.protokoll.mangel_aus_pruefpunkt', parameter),
  meineOffenenProtokolle: () =>
    methode('oekovolt_baudoku.api.protokoll.meine_offenen_protokolle', {}, 'GET'),
  zuVerifizieren: () => methode('oekovolt_baudoku.api.protokoll.zu_verifizieren', {}, 'GET'),
  messdatenTrend: (anlage: string, string_nr?: string) =>
