  anlagenKarte: (parameter: Record<string, unknown> = {}) =>
    methode('oekovolt_baudoku.baudoku.doctype.pv_anlage.pv_anlage.karte', parameter, 'GET'),
  anlagenUebersicht: (anlage: string) =>
    methode('frappe.client.get_value', { doctype: 'PV Anlage', filters: anlage }, 'GET').then(() =>
