export function positionEinmalig(): Promise<Position> {
  if (!gpsVerfuegbar()) return Promise.reject(new Error('Dieses Gerät liefert keine GPS-Daten.'))

  return new Promise((aufloesen, ablehnen) => {
    navigator.geolocation.getCurrentPosition(
      (treffer) =>
