          lat: treffer.coords.latitude,
          lng: treffer.coords.longitude,
          genauigkeit: treffer.coords.accuracy,
          zeitpunkt: new Date(treffer.timestamp).toISOString(),
        }),
      (fehler) => ablehnen(new Error(fehlertext(fehler))),
      OPTIONEN,
    )
  })
}

function fehlertext(fehler: GeolocationPositionError): string {
  switch (fehler.code) {
    case fehler.PERMISSION_DENIED:
      return 'Standortfreigabe verweigert. Die Position wird nicht mitgeschrieben.'
    case fehler.POSITION_UNAVAILABLE:
      return 'Keine Position verfügbar (kein GPS-Empfang).'
    case fehler.TIMEOUT:
      return 'Positionsbestimmung hat zu lange gedauert.'
    default:
      return 'Position konnte nicht bestimmt werden.'
  }
}

