export function formatiere(position: Position | null | undefined): string {
  if (!position) return ''
  const genau = position.genauigkeit ? ` (±${Math.round(position.genauigkeit)} m)` : ''
  return `${position.lat.toFixed(6)}, ${position.lng.toFixed(6)}${genau}`
}

/** Entfernung in Metern (Haversine) — für „Anlagen in meiner Nähe“. */
export function entfernung(a: { lat: number; lng: number }, b: { lat: number; lng: number }): number {
  const R = 6_371_000
  const bogen = (grad: number) => (grad * Math.PI) / 180
  const dLat = bogen(b.lat - a.lat)
  const dLng = bogen(b.lng - a.lng)
  const h =
    Math.sin(dLat / 2) ** 2 +
    Math.cos(bogen(a.lat)) * Math.cos(bogen(b.lat)) * Math.sin(dLng / 2) ** 2
  return Math.round(2 * R * Math.asin(Math.sqrt(h)))
}
