/** Formatierung für die Anzeige (Locale de-AT). */

const DATUM = new Intl.DateTimeFormat('de-AT', { day: '2-digit', month: '2-digit', year: 'numeric' })
const DATUM_ZEIT = new Intl.DateTimeFormat('de-AT', {
  day: '2-digit',
  month: '2-digit',
  year: 'numeric',
  hour: '2-digit',
  minute: '2-digit',
})
const ZAHL = new Intl.NumberFormat('de-AT', { maximumFractionDigits: 2 })

function alsDatum(wert: string | Date | null | undefined): Date | null {
  if (!wert) return null
  // Frappe liefert "2026-09-15 08:30:00" — ohne T interpretiert Safari das nicht.
  const datum = wert instanceof Date ? wert : new Date(String(wert).replace(' ', 'T'))
  return Number.isNaN(datum.getTime()) ? null : datum
}

export function datum(wert: string | Date | null | undefined, fallback = '–'): string {
  const d = alsDatum(wert)
  return d ? DATUM.format(d) : fallback
}

export function datumZeit(wert: string | Date | null | undefined, fallback = '–'): string {
  const d = alsDatum(wert)
  return d ? DATUM_ZEIT.format(d) : fallback
}

export function zahl(wert: number | null | undefined, einheit = '', fallback = '–'): string {
  if (wert === null || wert === undefined || Number.isNaN(wert)) return fallback
  return einheit ? `${ZAHL.format(wert)} ${einheit}` : ZAHL.format(wert)
}

export function prozent(wert: number | null | undefined): string {
  if (wert === null || wert === undefined) return '0 %'
  return `${Math.round(wert)} %`
}

/** „vor 3 Minuten“, „gestern“ … für Sync- und Aktivitätsanzeigen. */
export function relativ(wert: string | Date | null | undefined): string {
  const d = alsDatum(wert)
  if (!d) return 'nie'
  const sekunden = Math.round((Date.now() - d.getTime()) / 1000)
  if (sekunden < 60) return 'gerade eben'
  if (sekunden < 3600) return `vor ${Math.floor(sekunden / 60)} min`
  if (sekunden < 86_400) return `vor ${Math.floor(sekunden / 3600)} h`
  if (sekunden < 172_800) return 'gestern'
  return datum(d)
}

export function tageBis(wert: string | null | undefined): number | null {
  const d = alsDatum(wert)
  if (!d) return null
  const heute = new Date()
  heute.setHours(0, 0, 0, 0)
  d.setHours(0, 0, 0, 0)
  return Math.round((d.getTime() - heute.getTime()) / 86_400_000)
}

/** ISO-Datum (YYYY-MM-DD) für Frappe-Datumsfelder. */
export function isoDatum(wert: Date = new Date()): string {
  return wert.toISOString().slice(0, 10)
}

/** Frappe-Datetime ("YYYY-MM-DD HH:MM:SS") in lokaler Zeit. */
export function frappeDatetime(wert: Date = new Date()): string {
  const pad = (n: number) => String(n).padStart(2, '0')
  return (
    `${wert.getFullYear()}-${pad(wert.getMonth() + 1)}-${pad(wert.getDate())} ` +
    `${pad(wert.getHours())}:${pad(wert.getMinutes())}:${pad(wert.getSeconds())}`
  )
}

export function dateigroesse(bytes: number): string {
  if (bytes < 1024) return `${bytes} B`
  if (bytes < 1024 * 1024) return `${(bytes / 1024).toFixed(0)} kB`
  return `${(bytes / 1024 / 1024).toFixed(1)} MB`
}
