  const schweregrade = ref<Schweregrad[]>([])
  const geladen = ref(false)
  const ausCache = ref(false)
  const fehler = ref<string | null>(null)

  const rollen = computed(() => benutzer.value?.rollen ?? [])
  const istBauleiter = computed(() =>
    rollen.value.some((r) =>
      ['Baudoku Bauleiter', 'Baudoku Projektleiter', 'Baudoku Admin', 'System Manager'].includes(r),
