  )
  const istProjektleiter = computed(() =>
    rollen.value.some((r) => ['Baudoku Projektleiter', 'Baudoku Admin', 'System Manager'].includes(r)),
  )
  const istSubunternehmer = computed(
    () => rollen.value.includes('Baudoku Subunternehmer') && !istBauleiter.value,
  )
  const mitarbeiter = computed(() => benutzer.value?.mitarbeiter?.name ?? '')

  function uebernehmen(daten: Bootstrap) {
    benutzer.value = daten.benutzer
    einstellungen.value = { ...STANDARD_EINSTELLUNGEN, ...daten.einstellungen }
    anlagen.value = daten.anlagen ?? []
    vorlagen.value = daten.vorlagen ?? []
    kategorien.value = daten.mangelkategorien ?? []
    schweregrade.value = daten.schweregrade ?? []
    geladen.value = true
  }

  /** Lädt die Stammdaten; fällt bei fehlendem Netz auf den lokalen Cache zurück. */
  async function laden(): Promise<void> {
    fehler.value = null
    try {
      const daten = (await baudoku.bootstrap()) as Bootstrap
      uebernehmen(daten)
      ausCache.value = false
      await stammdatenSchreiben('bootstrap', daten)
    } catch (ausnahme) {
      const cache = await stammdatenLesen<Bootstrap>('bootstrap')
      if (cache) {
        uebernehmen(cache)
        ausCache.value = true
        fehler.value = 'Offline – Stammdaten aus dem lokalen Speicher.'
      } else {
        fehler.value = (ausnahme as Error).message
        throw ausnahme
      }
    }
  }

  function anlage(name: string): Anlage | undefined {
    return anlagen.value.find((a) => a.name === name)
  }

  function vorlage(name: string): Vorlage | undefined {
    return vorlagen.value.find((v) => v.name === name)
  }

  function schweregrad(code: string): Schweregrad | undefined {
    return schweregrade.value.find((s) => s.code === code || s.name === code)
  }

