/** Sync-Zustand für den Offline-Indikator (NFA-014). */

import { defineStore } from 'pinia'
import { computed, ref } from 'vue'

import { db, fotoPufferMb, warteschlangeGroesse } from '@/lib/db'
import { autoSyncStarten, beobachten, synchronisieren, type SyncZustand } from '@/lib/sync'

export const useSync = defineStore('sync', () => {
  const zustand = ref<SyncZustand>(navigator.onLine ? 'online' : 'offline')
  const ausstehend = ref(0)
  const konflikte = ref(0)
  const pufferMb = ref(0)
  const letzterSync = ref<string | null>(null)
  const letzteMeldung = ref('')
  let abmelden: (() => void) | null = null

  const istOffline = computed(() => zustand.value === 'offline')
  const laeuft = computed(() => zustand.value === 'syncing')
  const hatAusstehende = computed(() => ausstehend.value > 0)

  async function zaehlerAktualisieren() {
    ausstehend.value = await warteschlangeGroesse()
    konflikte.value = await db.konflikte.where('gesichtet').equals(0).count()
    pufferMb.value = await fotoPufferMb()
  }

  function starten() {
    if (abmelden) return
    const stoppAuto = autoSyncStarten()
    const stoppBeobachter = beobachten((neuerZustand, ergebnis) => {
      zustand.value = neuerZustand
      if (ergebnis) {
        letzteMeldung.value = ergebnis.meldung
        if (ergebnis.uebertragen || ergebnis.fotos) letzterSync.value = new Date().toISOString()
      }
      void zaehlerAktualisieren()
    })
    abmelden = () => {
      stoppAuto()
      stoppBeobachter()
      abmelden = null
    }
    void zaehlerAktualisieren()
  }

  async function jetztSynchronisieren() {
    const ergebnis = await synchronisieren()
    letzteMeldung.value = ergebnis.meldung
    await zaehlerAktualisieren()
    return ergebnis
  }

  async function konflikteLesen() {
    return db.konflikte.where('gesichtet').equals(0).toArray()
  }

  async function konfliktQuittieren(id: number) {
    await db.konflikte.update(id, { gesichtet: 1 })
    await zaehlerAktualisieren()
  }

  return {
    zustand,
    ausstehend,
    konflikte,
    pufferMb,
    letzterSync,
    letzteMeldung,
    istOffline,
    laeuft,
    hatAusstehende,
    starten,
    jetztSynchronisieren,
    zaehlerAktualisieren,
    konflikteLesen,
    konfliktQuittieren,
  }
})
