import router from './router'
import './style.css'

/**
 * Frappe legt den CSRF-Token in das Markup der Website-Page. Im Dev-Server
 * (Vite unter :8080, Bench unter :8000) fehlt er — dort kommt er aus dem Cookie.
 */
function csrfUebernehmen() {
  if (window.csrf_token) return
  const ausMeta = document.querySelector<HTMLMetaElement>('meta[name="csrf-token"]')?.content
  if (ausMeta) {
    window.csrf_token = ausMeta
    return
  }
  const ausCookie = document.cookie
    .split(';')
    .map((teil) => teil.trim().split('='))
    .find(([schluessel]) => schluessel === 'csrf_token')
  if (ausCookie) window.csrf_token = decodeURIComponent(ausCookie[1])
}

csrfUebernehmen()

const app = createApp(App)
app.use(createPinia())
app.use(router)

app.config.errorHandler = (fehler, _instanz, hinweis) => {
  console.error('Unbehandelter Fehler:', hinweis, fehler)
}

app.mount('#app')
