        ],
        nach_schweregrad: [
          { label: 'A', wert: 2 },
          { label: 'B', wert: 2 },
          { label: 'C', wert: 1 },
        ],
        nach_zustaendigem: [
          { label: 'HR-EMP-00007', wert: 3 },
