        ],
        aelteste: MAENGEL.slice(0, 3),
      }

    case 'oekovolt_baudoku.api.dashboard.baufortschritt':
      return [
        {
          anlage: 'ANL-2026-00002', anlage_name: 'Wohnpark Ostermiething', berichte: 12, stunden: 412,
          fortschritt: 62, letzter_bericht: tage(-1),
