/** Beantwortet eine Servermethode aus den Demodaten. `undefined` = nicht abgedeckt. */
export function demoAntwort(name: string, parameter: Record<string, unknown>): unknown {
  switch (name) {
    case 'oekovolt_baudoku.api.sync.bootstrap':
      return { ...BOOTSTRAP, server_zeit: new Date().toISOString() }

    case 'oekovolt_baudoku.api.sync.sync_status':
      return { letzter_sync: new Date().toISOString(), fehler_gesamt: 0, server_zeit: new Date().toISOString() }

    case 'oekovolt_baudoku.api.sync.push':
      return {
        ergebnisse: ((parameter.operationen as { lokale_id: string }[]) ?? []).map((op) => ({
          lokale_id: op.lokale_id,
          ergebnis: 'Erfolg',
          name: `DEMO-${op.lokale_id.slice(0, 8)}`,
          modified: new Date().toISOString(),
        })),
        server_zeit: new Date().toISOString(),
      }

    case 'oekovolt_baudoku.api.sync.foto_hochladen':
      return { file_url: '', name: 'demo', hash: 'demo', groesse: 0, dublette: false }

    case 'oekovolt_baudoku.api.protokoll.vorlage_komplett':
      return DEMO_VORLAGEN[String(parameter.vorlage)] ?? DEMO_VORLAGEN['CLV-0001']

    case 'oekovolt_baudoku.api.protokoll.vorlagen_fuer_anlage':
      return BOOTSTRAP.vorlagen

    case 'oekovolt_baudoku.api.protokoll.meine_offenen_protokolle':
      return PROTOKOLLE.filter((p) => ['Entwurf', 'In Arbeit'].includes(p.status))

    case 'oekovolt_baudoku.api.protokoll.zu_verifizieren':
      return PROTOKOLLE.filter((p) => p.status === 'Abgeschlossen')

    case 'oekovolt_baudoku.api.dashboard.kennzahlen':
      return {
        offene_maengel: MAENGEL.filter((m) => m.status !== 'Erledigt').length,
        ueberfaellige_maengel: MAENGEL.filter((m) => m.ueberfaellig).length,
        meine_maengel: 3,
        protokolle_in_arbeit: 1,
        protokolle_zu_verifizieren: 1,
        berichte_zur_freigabe: 1,
        anlagen_in_bau: 1,
        anlagen_gesamt: BOOTSTRAP.anlagen.length,
        wartungen_faellig: 2,
      }

    case 'oekovolt_baudoku.api.dashboard.mangel_dashboard':
      return {
        gesamt: MAENGEL.length,
        ueberfaellig: MAENGEL.filter((m) => m.ueberfaellig).length,
        nach_anlage: [
          { label: 'ANL-2026-00001', wert: 3 },
          { label: 'ANL-2026-00002', wert: 1 },
          { label: 'ANL-2026-00004', wert: 1 },
        ],
        nach_kategorie: [
          { label: 'Modul', wert: 1 },
          { label: 'DC-Verkabelung', wert: 1 },
          { label: 'Unterkonstruktion', wert: 1 },
          { label: 'Wallbox / Ladestation', wert: 1 },
          { label: 'Erdung und Blitzschutz', wert: 1 },
        ],
        nach_schweregrad: [
          { label: 'A', wert: 2 },
          { label: 'B', wert: 2 },
          { label: 'C', wert: 1 },
        ],
        nach_zustaendigem: [
          { label: 'HR-EMP-00007', wert: 3 },
          { label: 'nicht zugewiesen', wert: 2 },
        ],
        aelteste: MAENGEL.slice(0, 3),
      }

    case 'oekovolt_baudoku.api.dashboard.baufortschritt':
      return [
        {
          anlage: 'ANL-2026-00002', anlage_name: 'Wohnpark Ostermiething', berichte: 12, stunden: 412,
          fortschritt: 62, letzter_bericht: tage(-1),
          verlauf: [
            { datum: tage(-12), wert: 18 }, { datum: tage(-9), wert: 27 }, { datum: tage(-6), wert: 39 },
            { datum: tage(-3), wert: 48 }, { datum: tage(-2), wert: 55 }, { datum: tage(-1), wert: 62 },
          ],
        },
      ]

    case 'oekovolt_baudoku.api.dashboard.protokoll_statistik':
      return {
        jahr: heute.getFullYear(),
        je_monat: Array.from({ length: 12 }, (_, i) => ({
          monat: i + 1,
          werte: { Wartung: (i * 3) % 7, IBN: (i * 2) % 5, 'DC-Abnahme': i % 4 },
        })),
        bewertungen: [
          { label: 'Bestanden', wert: 42 },
          { label: 'Bestanden mit Auflagen', wert: 17 },
          { label: 'Nicht bestanden', wert: 3 },
        ],
        gesamt: 62,
      }

    case 'oekovolt_baudoku.baudoku.doctype.pv_anlage.pv_anlage.karte':
      return BOOTSTRAP.anlagen

    case 'oekovolt_baudoku.baudoku.doctype.pv_anlage.pv_anlage.anstehende_wartungen':
      return BOOTSTRAP.anlagen.filter((a) => a.naechste_wartung)

    case 'oekovolt_baudoku.baudoku.doctype.tagesbericht.tagesbericht.offene_freigaben':
      return BERICHTE.filter((b) => b.status === 'Eingereicht')

    case 'oekovolt_baudoku.baudoku.doctype.tagesbericht.tagesbericht.fortschritts_timeline':
      return BERICHTE

    case 'oekovolt_baudoku.api.pdf.erzeuge_pdf':
      return { file_url: '', file_name: 'demo.pdf' }

    case 'frappe.client.get_count':
      return 0

    case 'run_doc_method':
      if (parameter.method === 'uebersicht') {
        return {
          protokolle: PROTOKOLLE.filter((p) => p.anlage === parameter.dn),
          maengel: MAENGEL.filter((m) => m.anlage === parameter.dn),
          tagesberichte: BERICHTE.filter((b) => b.anlage === parameter.dn),
        }
      }
      return {}

    default:
      return undefined
  }
}

/** Ersatz für `/api/resource`-Listen im Demo-Modus. */
export function demoListe(doctype: string): unknown[] {
  switch (doctype) {
    case 'Mangel':
      return MAENGEL
    case 'Pruefprotokoll':
      return PROTOKOLLE
    case 'Tagesbericht':
      return BERICHTE
    case 'PV Anlage':
      return BOOTSTRAP.anlagen
    case 'Checklistenvorlage':
      return BOOTSTRAP.vorlagen
    default:
      return []
  }
}

