1	/**
2	 * Schmaler Frappe-Client.
3	 *
4	 * Bewusst ohne zusätzliche Abhängigkeit: Die App spricht ausschließlich
5	 * `/api/method` (Whitelisted-Methoden) und `/api/resource` (Doctype-CRUD) an.
6	 * Authentifiziert wird über das Session-Cookie der Frappe-Site; der CSRF-Token
7	 * kommt aus `window.csrf_token`, das die Website-Page `www/baudoku.py` setzt.
8	 */
9	
10	import { demoAktiv, demoAntwort, demoListe } from './demo'
11	
12	export class ApiFehler extends Error {
13	  constructor(
14	    message: string,
15	    readonly status: number,
16	    readonly exception?: string,
17	    readonly rohtext?: string,
18	  ) {
19	    super(message)
20	    this.name = 'ApiFehler'
21	  }
22	
23	  /** Netzwerkausfall statt inhaltlichem Fehler — der Sync darf es später erneut versuchen. */
24	  get istNetzfehler(): boolean {
25	    return this.status === 0
26	  }
27	
28	  get istAnmeldefehler(): boolean {
29	    return this.status === 401 || this.status === 403
30	  }
31	}
32	
33	declare global {
34	  interface Window {
35	    csrf_token?: string
36	    frappe_boot?: Record<string, unknown>
37	  }
38	}
39	
40	function csrfToken(): string {
41	  return window.csrf_token ?? ''
42	}
43	
44	function kopfzeilen(): HeadersInit {
45	  const kopf: Record<string, string> = {
46	    Accept: 'application/json',
47	    'Content-Type': 'application/json',
48	    'X-Requested-With': 'XMLHttpRequest',
49	  }
50	  const token = csrfToken()
51	  if (token) kopf['X-Frappe-CSRF-Token'] = token
52	  return kopf
53	}
54	
55	/** Entpackt Frappe-Fehlermeldungen (`_server_messages`, `exc_type`) in lesbaren Text. */
56	function fehlertext(daten: unknown, rohtext: string, status: number): string {
57	  if (daten && typeof daten === 'object') {
58	    const d = daten as Record<string, unknown>
59	    const messages = d._server_messages
60	    if (typeof messages === 'string') {
61	      try {
62	        const liste = JSON.parse(messages) as string[]
63	        const texte = liste.map((eintrag) => {
64	          try {
65	            const objekt = JSON.parse(eintrag) as { message?: string; title?: string }
66	            return objekt.message ?? objekt.title ?? eintrag
67	          } catch {
68	            return eintrag
69	          }
70	        })
71	        if (texte.length) return texte.join('\n').replace(/<[^>]+>/g, '')
72	      } catch {
73	        /* weiter unten */
74	      }
75	    }
76	    if (typeof d.message === 'string') return d.message
77	    if (typeof d.exc_type === 'string') return d.exc_type
78	  }
79	  if (rohtext && rohtext.length < 400) return rohtext.replace(/<[^>]+>/g, '').trim()
80	  return `Serverfehler (HTTP ${status})`
81	}
82	
83	async function anfrage<T>(pfad: string, optionen: RequestInit = {}): Promise<T> {
84	  let antwort: Response
85	  try {
86	    antwort = await fetch(pfad, {
87	      credentials: 'same-origin',
88	      headers: kopfzeilen(),
89	      ...optionen,
90	    })
91	  } catch (fehler) {
92	    throw new ApiFehler(
93	      'Keine Verbindung zum Server. Die Daten bleiben lokal gespeichert.',
94	      0,
95	      (fehler as Error)?.message,
96	    )
97	  }
98	
99	  const rohtext = await antwort.text()
100	  let daten: unknown = null
101	  if (rohtext) {
102	    try {
103	      daten = JSON.parse(rohtext)
104	    } catch {
105	      daten = null
106	    }
107	  }
108	
109	  if (!antwort.ok) {
110	    const exception = (daten as { exc_type?: string } | null)?.exc_type
111	    throw new ApiFehler(fehlertext(daten, rohtext, antwort.status), antwort.status, exception, rohtext)
112	  }
113	
114	  const inhalt = daten as { message?: T; data?: T } | null
115	  if (inhalt && 'message' in inhalt) return inhalt.message as T
116	  if (inhalt && 'data' in inhalt) return inhalt.data as T
117	  return daten as T
118	}
119	
120	/** Ruft eine whitelisted Servermethode auf. */
121	export function methode<T = unknown>(
122	  name: string,
123	  parameter: Record<string, unknown> = {},
124	  methodeHttp: 'GET' | 'POST' = 'POST',
125	): Promise<T> {
126	  if (demoAktiv()) {
127	    const antwort = demoAntwort(name, parameter)
128	    if (antwort !== undefined) return Promise.resolve(antwort as T)
129	  }
130	  const pfad = `/api/method/${name}`
131	  if (methodeHttp === 'GET') {
132	    const query = new URLSearchParams()
133	    for (const [schluessel, wert] of Object.entries(parameter)) {
134	      if (wert === undefined || wert === null) continue
135	      query.set(schluessel, typeof wert === 'object' ? JSON.stringify(wert) : String(wert))
136	    }
137	    const suffix = query.toString()
138	    return anfrage<T>(suffix ? `${pfad}?${suffix}` : pfad, { method: 'GET' })
139	  }
