    if (geaendert) await db.protokolle.put(protokoll)
  }

  for (const mangel of await db.maengel.toArray()) {
    const geaendert = ersetzeIn(mangel.fotos) || ersetzeIn(mangel.erledigt_fotos)
    if (geaendert) await db.maengel.put(mangel)
