import pathlib

def patch(pfad, paare):
    p = pathlib.Path(pfad); s = p.read_text(encoding='utf-8')
    for alt, neu in paare:
        if alt not in s:
            raise SystemExit(f'NICHT GEFUNDEN in {pfad}:\n---\n{alt[:200]}\n---')
        s = s.replace(alt, neu, 1)
    p.write_text(s, encoding='utf-8')
    print('ok', pfad)

patch('oekovolt_baudoku/baudoku/doctype/pruefprotokoll/pruefprotokoll.py', [

 # Abschlusspruefung und Mangelnachtrag greifen auch auf dem Sync-Weg
 ("""	def validate(self):
		self.vorlage_revision_festhalten()
		self.plausibilitaet_pruefen()
		self.fortschritt_berechnen()
		self.dauer_berechnen()
		self.gesamtbewertung_pruefen()

	def on_update(self):
		if self.status in ("Abgeschlossen", "Verifiziert"):
			self.anlage_aktualisieren()""",
  """	def validate(self):
		self.vorlage_revision_festhalten()
		self.plausibilitaet_pruefen()
		self.fortschritt_berechnen()
		self.dauer_berechnen()
		self.gesamtbewertung_pruefen()
		if self.wird_abgeschlossen():
			self.abschluss_pruefen()
			if not self.abschluss_datum:
				self.abschluss_datum = now_datetime()

	def on_update(self):
		if self.status in ("Abgeschlossen", "Verifiziert"):
			self.anlage_aktualisieren()
		# Ein offline abgeschlossenes Protokoll kommt ueber den Sync herein und
		# ruft `abschliessen()` nie auf. Die Mangelanlage muss trotzdem laufen.
		if self.wird_abgeschlossen():
			neue = self.maengel_erzeugen()
			if neue:
				frappe.db.set_value(
					self.doctype, self.name, "anzahl_maengel",
					cint(self.anzahl_maengel) + len(neue), update_modified=False,
				)

	def wird_abgeschlossen(self) -> bool:
		\"\"\"Wechselt dieses Dokument gerade in den Status 'Abgeschlossen'?\"\"\"
		if self.status != "Abgeschlossen":
			return False
		vorher = self.get_doc_before_save()
		return not vorher or vorher.status != "Abgeschlossen\""""),

 # Pruefung als eigene Methode, damit Sync und Whitelist-Aufruf dieselbe nutzen
 ("""	@frappe.whitelist()
	def abschliessen(self, gesamtbewertung: str | None = None, zusammenfassung: str | None = None):
		\"\"\"Schliesst das Protokoll ab, erzeugt Maengel und aktualisiert die Anlage.\"\"\"
		if self.status in ("Abgeschlossen", "Verifiziert"):
			return {"status": self.status, "maengel": []}

		offen = self.pflichtfelder_offen()
		if offen:
			frappe.throw(
				_("{0} Pflichtangaben fehlen, z. B. {1}.").format(
					len(offen), ", ".join(f"{o['nummer']} ({o['grund']})" for o in offen[:3])
				),
				title=_("Protokoll unvollstaendig"),
			)

		if not any(u.rolle in ("Techniker", "Pruefer") for u in self.unterschriften):
			frappe.throw(_("Die Unterschrift des Technikers fehlt."), title=_("Unterschrift fehlt"))

		if gesamtbewertung:
			self.gesamtbewertung = gesamtbewertung
		if zusammenfassung:
			self.zusammenfassung = zusammenfassung

		maengel = self.maengel_erzeugen()
		self.anzahl_maengel = len(maengel) + cint(self.anzahl_maengel)
		self.abschluss_datum = now_datetime()
		self.status = "Abgeschlossen"
		self.save()

		return {"status": self.status, "maengel": maengel}""",
  """	def abschluss_pruefen(self):
		\"\"\"Vollstaendigkeit und Unterschrift — gilt fuer jeden Weg zum Abschluss.

		Der Offline-Client prueft dasselbe bereits, aber er ist nicht die
		massgebliche Instanz: Ein manipulierter oder veralteter Client darf kein
		unvollstaendiges Protokoll in den Bestand schreiben (NFA-042, AK-07).
		\"\"\"
		offen = self.pflichtfelder_offen()
		if offen:
			frappe.throw(
				_("{0} Pflichtangaben fehlen, z. B. {1}.").format(
					len(offen), ", ".join(f"{o['nummer']} ({o['grund']})" for o in offen[:3])
				),
				title=_("Protokoll unvollstaendig"),
			)

		if not any(u.rolle in ("Techniker", "Pruefer") for u in self.unterschriften):
			frappe.throw(_("Die Unterschrift des Technikers fehlt."), title=_("Unterschrift fehlt"))

	@frappe.whitelist()
	def abschliessen(self, gesamtbewertung: str | None = None, zusammenfassung: str | None = None):
		\"\"\"Schliesst das Protokoll ab, erzeugt Maengel und aktualisiert die Anlage.\"\"\"
		if self.status in ("Abgeschlossen", "Verifiziert"):
			return {"status": self.status, "maengel": []}

		if gesamtbewertung:
			self.gesamtbewertung = gesamtbewertung
		if zusammenfassung:
			self.zusammenfassung = zusammenfassung

		# Pruefung und Mangelanlage laufen in validate/on_update.
		self.status = "Abgeschlossen"
		self.save()

		return {
			"status": self.status,
			"maengel": [z.mangel for z in self.ergebnisse if z.mangel],
		}"""),

 # Zahlenwert 0 ist ein gueltiger Messwert
 ("""	@staticmethod
	def _zeile_befuellt(zeile) -> bool:
		return bool(
			zeile.bewertung
			or zeile.wert_text
			or zeile.wert_datum
			or zeile.wert_ja_nein
			or zeile.wert_zahl not in (None, 0)
			or zeile.fotos
		)""",
  """	@staticmethod
	def _zeile_befuellt(zeile) -> bool:
		\"\"\"Gilt die Zeile als erfasst?

		Frappe-Float-Felder sind nie ``None``, sondern ``0.0`` — eine gemessene
		Null waere sonst nicht von 'noch nichts eingetragen' zu unterscheiden.
		Deshalb zaehlt zusaetzlich der vom Client gesetzte Status: Er steht nur
		dann nicht mehr auf 'Offen', wenn tatsaechlich etwas erfasst wurde.
		\"\"\"
		return bool(
			zeile.bewertung
			or zeile.wert_text
			or zeile.wert_datum
			or zeile.wert_ja_nein
			or zeile.wert_zahl
			or zeile.fotos
			or (zeile.status and zeile.status != "Offen")
		)"""),
])
