FE = pathlib.Path(r"C:\Users\SALEADMIN\Documents\Servicetechniker APP\frontend")


def patch(pfad, paare):
    p = FE / pfad
    s = p.read_text(encoding="utf-8")
    for alt, neu in paare:
        if alt not in s:
            raise SystemExit(f"NICHT GEFUNDEN in {pfad}:\n---\n{alt[:300]}\n---")
