    trace: 'retain-on-failure',
    screenshot: 'only-on-failure',
    locale: 'de-AT',
    timezoneId: 'Europe/Vienna',
    // Ohne vorab erteilte Freigabe blockiert die Standortabfrage beim
    // Protokollstart bis zum Zeitlimit.
    permissions: ['geolocation'],
    geolocation: { latitude: 48.0655, longitude: 12.8452 },
  },

  projects: [
    {
      name: 'tablet',
      use: { ...devices['Galaxy Tab S4 landscape'] },
    },
    {
      name: 'smartphone',
      use: { ...devices['Pixel 5'] },
    },
    {
      name: 'desktop',
      use: { ...devices['Desktop Chrome'], viewport: { width: 1440, height: 900 } },
