neu = """import { fileURLToPath, URL } from 'node:url'
import { copyFileSync, existsSync, mkdirSync, readdirSync } from 'node:fs'
import { resolve } from 'node:path'"""
assert alt in s
s = s.replace(alt, neu, 1)

alt2 = """/** Kopiert das Build-Ergebnis als Frappe-Website-Page nach `www/baudoku.html`. */
function frappeWebsitePage(): Plugin {
  return {
    name: 'frappe-website-page',
    apply: 'build',
    closeBundle() {
