import { chromium } from '@playwright/test'

const browser = await chromium.launch()
const page = await browser.newContext({ locale: 'de-AT' }).then((k) => k.newPage())
page.on('console', (m) => console.log(`[${m.type()}]`, m.text().slice(0, 250)))
page.on('pageerror', (e) => console.log('[pageerror]', e.message))
page.on('requestfailed', (r) => console.log('[failed]', r.url().slice(0, 120), r.failure()?.errorText))

await page.goto('http://localhost:8081/baudoku')
await page.waitForTimeout(5000)

const zustand = await page.evaluate(async () => {
  const r = await navigator.serviceWorker?.getRegistration()
  return {
    unterstuetzt: 'serviceWorker' in navigator,
    registrierung: r ? { scope: r.scope, aktiv: Boolean(r.active), wartet: Boolean(r.waiting) } : null,
    controller: Boolean(navigator.serviceWorker?.controller),
  }
})
console.log('SW:', JSON.stringify(zustand))
console.log('Text:', (await page.locator('body').innerText()).slice(0, 200).replace(/\n/g, ' | '))

await browser.close()

