import { chromium } from '@playwright/test'

const browser = await chromium.launch()
const page = await browser.newContext().then((k) => k.newPage())
page.on('console', (m) => console.log(`[${m.type()}]`, m.text().slice(0, 300)))
page.on('pageerror', (e) => console.log('[pageerror]', e.message))

await page.goto('http://localhost:8081/baudoku')
await page.waitForTimeout(3000)

const ergebnis = await page.evaluate(async () => {
  try {
    const r = await navigator.serviceWorker.register('/sw.js', { scope: '/baudoku' })
    return { ok: true, scope: r.scope, aktiv: Boolean(r.active), installiert: Boolean(r.installing) }
  } catch (e) {
    return { ok: false, fehler: String(e) }
  }
})
console.log('Manuelle Registrierung:', JSON.stringify(ergebnis))

await page.waitForTimeout(4000)
console.log(
  'Danach:',
  JSON.stringify(
    await page.evaluate(async () => {
      const r = await navigator.serviceWorker.getRegistration()
      return { vorhanden: Boolean(r), aktiv: Boolean(r?.active), scope: r?.scope }
    }),
  ),
)

await browser.close()

