import { chromium } from '@playwright/test'

const browser = await chromium.launch()
const kontext = await browser.newContext()
const page = await kontext.newPage()
page.on('console', (m) => console.log(`[${m.type()}]`, m.text().slice(0, 300)))
page.on('pageerror', (e) => console.log('[pageerror]', e.message))
page.on('requestfailed', (r) => console.log('[failed]', r.url().slice(0, 130), r.failure()?.errorText))
page.on('response', (r) => {
  if (r.status() >= 400) console.log('[http]', r.status(), r.url().slice(0, 130))
})

await page.goto('http://localhost:8081/baudoku')
await page.waitForTimeout(6000)

console.log(
  'Zustand:',
  JSON.stringify(
    await page.evaluate(async () => {
      const alle = await navigator.serviceWorker.getRegistrations()
      return {
        anzahl: alle.length,
        details: alle.map((r) => ({
          scope: r.scope,
          aktiv: Boolean(r.active),
          wartet: Boolean(r.waiting),
          installiert: Boolean(r.installing),
        })),
        controller: Boolean(navigator.serviceWorker.controller),
      }
    }),
  ),
)

await browser.close()

