import { chromium } from '@playwright/test'

const browser = await chromium.launch()
const page = await browser.newContext().then((k) => k.newPage())
page.on('response', (r) => {
  if (r.status() >= 400) console.log('[http]', r.status(), r.url().slice(0, 120))
})

const zustand = async () =>
  JSON.stringify(
    await page.evaluate(async () => {
      const r = await navigator.serviceWorker.getRegistration()
      return {
        scope: r?.scope,
        installing: r?.installing?.state,
        waiting: r?.waiting?.state,
        active: r?.active?.state,
        controller: Boolean(navigator.serviceWorker.controller),
        url: location.href,
      }
    }),
  )

await page.goto('http://localhost:8081/baudoku')
await page.waitForTimeout(5000)
console.log('nach erstem Laden:', await zustand())

await page.reload()
await page.waitForTimeout(3000)
console.log('nach Reload:     ', await zustand())

await page.reload()
await page.waitForTimeout(3000)
console.log('nach 2. Reload:  ', await zustand())

await browser.close()

