# API-Aufruf liefert nichts anderes.
# ----------------------------------------------------------------------------


def _eigener_supplier() -> str | None:
	"""Firma des angemeldeten Benutzers — Portalkonto oder Polier."""
	cache = getattr(frappe.local, "baudoku_subu_cache", None)
	if cache is not None:
		return cache

	supplier = _portal_zuordnung("Supplier") or frappe.db.get_value(
		"Subunternehmer Mitarbeiter", {"benutzer": frappe.session.user}, "supplier"
	)
	frappe.local.baudoku_subu_cache = supplier
	return supplier


def _nur_eigene_firma(tabelle: str, feld: str = "supplier") -> str:
	if _hat_vollzugriff():
		return ""
	supplier = _eigener_supplier()
	if not supplier:
		return _q("1 = 0")
	return _q(f"`tab{tabelle}`.{feld} = {frappe.db.escape(supplier)}")


def auftrag_query(user: str | None = None) -> str:
	return _nur_eigene_firma("Subunternehmerauftrag")


