def subu_mitarbeiter_query(user: str | None = None) -> str:
	return _nur_eigene_firma("Subunternehmer Mitarbeiter")


def subu_dokument_permission(doc, user: str | None = None, permission_type: str | None = None) -> bool:
	"""Einzeldokumentpruefung fuer alle Portalobjekte."""
	if _hat_vollzugriff():
		return True
	supplier = _eigener_supplier()
	if not supplier or doc.get("supplier") != supplier:
		return False

	# Was der Subunternehmer nicht mehr aendern darf, sobald es entschieden ist.
	if permission_type in ("write", "delete"):
		gesperrt = {
			"Subunternehmerauftrag": ("Abgenommen", "Storniert", "Abgelehnt"),
			"Materialanforderung": ("Bestellt", "Geliefert", "Abgelehnt"),
			"Personalmeldung": ("Gemeldet",),
			"Arbeitstag": ("Freigegeben", "Abgerechnet"),
		}.get(doc.doctype, ())
		if doc.get("status") in gesperrt:
			return False
		if doc.doctype == "Bauvertragsmeldung" and doc.get("gesperrt"):
			return False

	return True
