        pause_minuten: kurzePause ? 15 : 30,
        pause_ausreichend: kurzePause ? 0 : 1,
        ueber_tagesgrenze: lang ? 1 : 0,
        ueber_wochengrenze: 0,
        status: i <= 2 ? 'Vollstaendig' : 'Freigegeben',
        hinweise: lang
          ? 'Arbeitszeit 11.00 h ueber der Tagesgrenze von 10.0 h.'
          : kurzePause
            ? 'Ruhepause 15 min, erforderlich 30 min.'
            : '',
      })
    }
  }
  return liste
})()

const MATERIALANFORDERUNGEN: Record<string, unknown>[] = [
  {
    name: 'MAF-2026-00014', supplier: SUPPLIER, anlage: 'ANL-2026-00002',
    auftrag: 'SUA-2026-00031', status: 'Bestellt', benoetigt_am: tage(1),
    dringlichkeit: 'Morgen', begruendung: 'Dachhaken reichen nur bis Reihe 9.',
    antwort: 'Wird morgen frueh mit dem Materialtransport geliefert.', lieferdatum: tage(1),
    positionen: [
      { beschreibung: 'Dachhaken verstellbar', menge: 60, einheit: 'Stk' },
      { beschreibung: 'Montageschiene 4,4 m', menge: 20, einheit: 'Stk' },
    ],
  },
]

const BAUVERTRAGSMELDUNGEN: Record<string, unknown>[] = [
  {
    name: 'BVM-2026-00007', supplier: SUPPLIER, art: 'Behinderungsanzeige',
    betreff: 'Kran am Vormittag nicht verfuegbar', anlage: 'ANL-2026-00002',
    auftrag: 'SUA-2026-00028', status: 'Anerkannt',
    eingetreten_am: tage(-5) + ' 07:15:00', gemeldet_am: tage(-5) + ' 08:40:00',
    verzoegerung_stunden: 1, auswirkung_frist_tage: 2,
    beschreibung: 'Der Kran war bis 12:00 durch das Vorgewerk belegt.',
    antwort: 'Behinderung anerkannt, Frist um zwei Tage verlaengert.', anerkannte_frist_tage: 2,
  },
]

const PERSONALMELDUNGEN: Record<string, unknown>[] = []

'''

PORTAL_FAELLE = '''    // --- Subunternehmerportal ---------------------------------------------
    case 'oekovolt_baudoku.api.subunternehmer.portal_bootstrap':
      return {
        supplier: SUPPLIER,
        firmenname: SUPPLIER,
        ich: { name: 'SUM-0001', vollname: 'Ivan Horvat', ist_polier: 1 },
        ist_polier: true,
        kolonne: KOLONNE,
        meldepflicht: MELDEPFLICHT,
        baustellen: PORTAL_BAUSTELLEN,
        einstellungen: { geofence_radius_m: 300, geofence_erzwingen: false, fristwarnung_tage: 3 },
        server_zeit: new Date().toISOString(),
      }

    case 'oekovolt_baudoku.api.subunternehmer.meine_auftraege':
      return parameter.mit_erledigten
        ? PORTAL_AUFTRAEGE
        : PORTAL_AUFTRAEGE.filter((a) => a.status !== 'Abgenommen' && a.status !== 'Storniert')

    case 'oekovolt_baudoku.api.subunternehmer.kalender':
      return PORTAL_AUFTRAEGE.map((a) => ({ ...a, baustelle: PORTAL_BAUSTELLEN[0] ?? null }))

    case 'oekovolt_baudoku.api.subunternehmer.tagesuebersicht':
      return {
        auftraege_heute: PORTAL_AUFTRAEGE
          .filter((a) => a.status === 'In Arbeit' || a.status === 'Angenommen')
          .map((a) => ({ ...a, baustelle: PORTAL_BAUSTELLEN[0] ?? null })),
        fristwarnungen: PORTAL_AUFTRAEGE.filter((a) => a.fristwarnung_aktiv && !a.verzug),
        im_verzug: PORTAL_AUFTRAEGE.filter((a) => a.verzug),
        personalmeldung: {
          ...MELDEPFLICHT,
          abgegeben: PERSONALMELDUNGEN.length > 0,
          meldung: PERSONALMELDUNGEN[0] ?? null,
        },
        offene_materialanforderungen: MATERIALANFORDERUNGEN.filter(
          (m) => m.status !== 'Geliefert' && m.status !== 'Abgelehnt',
        ).length,
        offene_meldungen: BAUVERTRAGSMELDUNGEN.filter((m) => m.status === 'Gemeldet').length,
      }

    case 'oekovolt_baudoku.api.subunternehmer.fortschritt_melden': {
      const treffer = PORTAL_AUFTRAEGE.find((a) => a.name === parameter.auftrag)
      if (treffer) {
        treffer.fortschritt_prozent = Number(parameter.fortschritt)
        if (treffer.status === 'Angenommen' && treffer.fortschritt_prozent > 0) {
          treffer.status = 'In Arbeit'
        }
      }
      return { status: treffer?.status, fortschritt: treffer?.fortschritt_prozent }
    }

    case 'oekovolt_baudoku.api.subunternehmer.arbeitszeiten':
      return ARBEITSTAGE

    case 'oekovolt_baudoku.baudoku.doctype.stempelung.stempelung.offener_status':
      return (
        STEMPELZUSTAND[String(parameter.mitarbeiter)] ?? { eingestempelt: false, in_pause: false }
      )

    case 'oekovolt_baudoku.baudoku.doctype.stempelung.stempelung.stempeln': {
      const person = String(parameter.mitarbeiter)
      const richtung = String(parameter.richtung)
      STEMPELZUSTAND[person] = {
        eingestempelt: richtung === 'Ein' || richtung === 'Pause Ende',
        in_pause: richtung === 'Pause Beginn',
        seit: new Date().toISOString(),
      }
      return {
        name: `STP-DEMO-${Date.now()}`,
        zeitpunkt: new Date().toISOString(),
        innerhalb_geofence: true,
        entfernung_m: 42,
        ortung_verweigert: false,
        dublette: false,
      }
    }

    case 'oekovolt_baudoku.baudoku.doctype.arbeitstag.arbeitstag.zur_freigabe':
      return ARBEITSTAGE.filter((t) => t.status === 'Vollstaendig')

    case 'oekovolt_baudoku.baudoku.doctype.arbeitstag.arbeitstag.sammelfreigabe': {
      const namen = (parameter.namen as string[]) ?? []
      for (const tag of ARBEITSTAGE) {
        if (namen.includes(tag.name)) tag.status = 'Freigegeben'
      }
      return { erfolgreich: namen, fehlgeschlagen: [] }
    }

    case 'oekovolt_baudoku.baudoku.doctype.personalmeldung.personalmeldung.meldepflicht':
      return MELDEPFLICHT

    case 'oekovolt_baudoku.baudoku.doctype.personalmeldung.personalmeldung.heutige_meldung':
      return PERSONALMELDUNGEN[0] ?? null

    case 'oekovolt_baudoku.baudoku.doctype.subunternehmerauftrag.subunternehmerauftrag.auftrag_aus_mangel':
      return 'SUA-2026-00033'

'''

RUN_DOC_METHOD = '''    case 'run_doc_method': {
      if (parameter.method === 'uebersicht') {
        return {
          protokolle: PROTOKOLLE.filter((p) => p.anlage === parameter.dn),
          maengel: MAENGEL.filter((m) => m.anlage === parameter.dn),
          tagesberichte: BERICHTE.filter((b) => b.anlage === parameter.dn),
        }
      }

      const args = JSON.parse(String(parameter.args ?? '{}')) as Record<string, unknown>

      // Statuswechsel am Subunternehmerauftrag, damit sich das Portal
      // durchspielen laesst.
      if (parameter.dt === 'Subunternehmerauftrag') {
        const auftrag = PORTAL_AUFTRAEGE.find((a) => a.name === parameter.dn)
        if (auftrag && parameter.method === 'annehmen') auftrag.status = 'Angenommen'
        if (auftrag && parameter.method === 'fertigmelden') {
          auftrag.status = 'Fertiggemeldet'
          auftrag.fortschritt_prozent = 100
          auftrag.fertigmeldung_bemerkung = String(args.bemerkung ?? '')
        }
        return {}
      }

      if (parameter.dt === 'Arbeitstag' && parameter.method === 'beanstanden') {
        const tag = ARBEITSTAGE.find((t) => t.name === parameter.dn)
        if (tag) {
          tag.status = 'Beanstandet'
          tag.beanstandung = String(args.grund ?? '')
        }
        return {}
      }

      return {}
    }
'''

DEMO_ANLEGEN = '''/**
 * Schreibende Aufrufe im Demo-Modus.
 *
 * Es geht nichts an einen Server, aber das Ergebnis landet in den Demodaten —
 * damit sich Personalmeldung, Materialanforderung und Bauvertragsmeldung
 * vollstaendig durchspielen lassen.
 */
export function demoAnlegen(
  doctype: string,
  daten: Record<string, unknown>,
): Record<string, unknown> {
  const doc: Record<string, unknown> = {
    ...daten,
    name: daten.name ?? `${doctype.slice(0, 3).toUpperCase()}-DEMO-${Date.now()}`,
    modified: new Date().toISOString(),
  }

  if (doctype === 'Personalmeldung') {
    doc.gemeldet_am = new Date().toISOString()
    doc.alle_nachweise_gueltig = 1
    PERSONALMELDUNGEN.splice(0, PERSONALMELDUNGEN.length, doc)
  }
  if (doctype === 'Materialanforderung') {
    MATERIALANFORDERUNGEN.unshift(doc)
  }
  if (doctype === 'Bauvertragsmeldung') {
    doc.gemeldet_am = new Date().toISOString()
    doc.verzoegerung_stunden = 0
    BAUVERTRAGSMELDUNGEN.unshift(doc)
  }
  return doc
}

'''

