cd "C:/Users/SALEADMIN/Documents/Servicetechniker APP/frontend" && cat > e2e/portal.spec.ts <<'TSEOF'
import { expect, test, type Page } from '@playwright/test'

/**
 * Subunternehmerportal: der Tagesablauf eines Poliers.
 *
 * Geprüft wird, was vertraglich verlangt ist — Personal melden, stempeln,
 * Auftrag annehmen und fertigmelden — und die Fristwarnung, die den
 * Subunternehmer rechtzeitig auf das Fristende stößt.
 *
 * `?rolle=subu` schaltet den Demo-Modus in die Subunternehmerrolle. Der
 * Parameter wird beim Laden des Moduls einmal ausgewertet und gilt danach für
 * die ganze Sitzung, auch über Routenwechsel hinweg.
 */
async function portalOeffnen(page: Page, pfad = '/baudoku/portal') {
  const trenner = pfad.includes('?') ? '&' : '?'
  await page.goto(`${pfad}${trenner}rolle=subu`)
  await expect(page.getByText('Baudoku wird geladen')).toBeHidden({ timeout: 20_000 })
}

test.describe('Portalstart', () => {
  test('zeigt Firma, Verzug, Fristwarnung und die heutigen Aufträge', async ({ page }) => {
    await portalOeffnen(page)

    await expect(page.getByRole('heading', { name: 'Elektro Mayrhofer GmbH' })).toBeVisible()
    await expect(page.getByText('Ivan Horvat · Polier')).toBeVisible()

    // Was die Frist betrifft, muss ohne Rechnen ablesbar sein
    await expect(page.getByRole('heading', { name: 'In Verzug' })).toBeVisible()
    await expect(page.getByRole('heading', { name: 'Frist läuft ab' })).toBeVisible()
    await expect(page.getByText('noch 2 Tage')).toBeVisible()

    await expect(page.getByRole('heading', { name: 'Heute' })).toBeVisible()
    await expect(
      page.getByRole('link', { name: /Unterkonstruktion Feld C montieren/ }).first(),
    ).toBeVisible()
  })

  test('drängt zur Personalmeldung, solange sie fehlt', async ({ page }) => {
    await portalOeffnen(page)

    const hinweis = page.getByRole('link', { name: /Personalmeldung fehlt/ })
    await expect(hinweis).toBeVisible()
    await hinweis.click()

    await expect(page.getByRole('heading', { name: 'Personalmeldung' })).toBeVisible()
    await expect(page.getByText('Dragan Petrovic')).toBeVisible()
    // Ablaufender Nachweis muss vor der Kontrolle auffallen, nicht bei ihr
    await expect(page.getByText(/Nachweis läuft in \d+ Tagen ab/)).toBeVisible()

    await page.getByRole('button', { name: /4 Personen melden/ }).click()
    await expect(page.getByText('Für heute gemeldet')).toBeVisible()

    await portalOeffnen(page)
    await expect(page.getByRole('link', { name: /Personalmeldung fehlt/ })).toBeHidden()
  })
})

test.describe('Stempeluhr', () => {
  test('Polier stempelt seine Kolonne ein, in die Pause und aus', async ({ page }) => {
    await portalOeffnen(page)

    // Der Polier sieht alle vier — ohne Polierrolle wäre es nur er selbst
    const karten = page.locator('article').filter({ hasText: 'Marek Nowak' })
    await expect(karten).toHaveCount(1)
    await expect(karten.getByText('abwesend')).toBeVisible()

    await karten.getByRole('button', { name: 'Einstempeln' }).click()
    await expect(karten.getByText('anwesend')).toBeVisible()

    await karten.getByRole('button', { name: 'Pause', exact: true }).click()
    await expect(karten.getByText('in Pause')).toBeVisible()

    await karten.getByRole('button', { name: 'Pause beenden' }).click()
    await expect(karten.getByText('anwesend')).toBeVisible()

    await karten.getByRole('button', { name: 'Ausstempeln' }).click()
    await expect(karten.getByText('abwesend')).toBeVisible()
  })
})

test.describe('Aufträge', () => {
  test('Liste und Kalender zeigen dieselben Termine', async ({ page }) => {
    await portalOeffnen(page, '/baudoku/portal/auftraege')

    await expect(
      page.getByRole('link', { name: /Unterkonstruktion Feld C montieren/ }),
    ).toBeVisible()
